    const k = stockKey(cat, r);
    if (!inv[k]) inv[k] = { key: k, cat, grade: r.grade || '', item: r.item || '', unit: cat === 'feed' ? 'kg' : (r.unit || ''), label: stockLabel(cat, r), bought: 0, used: 0, cost: 0, boughtAll: 0, costAll: 0 };
    return inv[k];
