    if (hidden(r) || r.kind !== 'event' || !USAGE_TYPES.includes(r.type) || !r.qty) continue;
    if (r.amount != null && r.amount !== '' && !inv[stockKey(r.type, r)]) continue; // bought outside the app, cost entered directly
