        <div class="stat"><b>${shortMoney(td.cash)}</b><span>💵 Cash</span></div>
        <div class="stat"><b>${shortMoney(td.qr)}</b><span>📱 QR</span></div>
        <div class="stat"><b>${shortMoney(td.goods)}</b><span>📦 Goods</span></div>
      </div>
    </div>
    <div class="grid2">
      <div class="card tight"><div class="label">This week</div><div style="font-size:21px;font-weight:900">${money(wk.total)}</div><div class="small muted">Goods ${money(wk.goods)}</div></div>
      <div class="card tight"><div class="label">${BS_MONTHS[adToBs(t).m - 1]}</div><div style="font-size:21px;font-weight:900">${money(mo.total)}</div><div class="small muted">Goods ${money(mo.goods)}</div></div>
