      voice: t => { const x = normalize(t).s; return /\bcash\b/.test(x) ? 'cash' : /\bqr\b/.test(x) ? 'qr' : /\b(goods|bought)\b/.test(x) ? 'goods' : undefined; },
      voiceMode: v, onAnswer: k => { p[k] = p.loose; p.loose = null; flowShop(p, v); } });
    return;
  }
